def main():
    from collections import defaultdict
    from figure_backlog_common import parse_existing_ts

    ids, keys = parse_existing_ts()
    by_line = defaultdict(list)
    for item in RAW:
        by_line[item[3]].append(item)

    quotas = {
        "Marvel Legends": 70,
        "Star Wars Black Series": 45,
        "GI Joe Classified": 35,
        "Transformers Studio Series": 18,
        "Transformers Legacy": 15,
        "Lightning Collection": 17,
        "Super7 ULTIMATES": 13,
        "Super7 ReAction": 3,
        "H.A.C.K.S.": 10,
        "BST AXN": 12,
        "Masters of the Universe Masterverse": 12,
    }

    b = BatchBuilder(ids, keys, target_min=180, target_max=250)
    for line, quota in quotas.items():
        for item in by_line.get(line, [])[:quota]:
            extra = item[10] if len(item) > 10 else None
            b.try_add(
                item[0], item[1], item[2], item[3], item[4], item[5], item[6],
                scale=item[7], demand=item[8], tags=item[9], kind="figure", extra=extra,
            )
    for line, items in by_line.items():
        for item in items:
            if not b.room():
                break
            extra = item[10] if len(item) > 10 else None
            b.try_add(
                item[0], item[1], item[2], item[3], item[4], item[5], item[6],
                scale=item[7], demand=item[8], tags=item[9], kind="figure", extra=extra,
            )

    b.finalize()
    report = b.report()
    if report["count"] < 180:
        raise SystemExit(f"batch too small: {report['count']}")
    out = b.write(
        "batch-001",
        "Hasbro core expansions + select third-party",
        "Marvel Legends, Black Series, Classified, Studio Series/Legacy, Lightning Collection, Super7, Boss Fight, Loyal Subjects, Masterverse",
        status="queued",
    )
    man = {
        "strategy": "inject-one-batch-every-~3-weeks-with-noteworthy-promotion",
        "targetBatchSize": [180, 250],
        "lastInjectedAt": None,
        "lastInjectedBatch": None,
        "queued": ["batch-001"],
        "injected": [],
    }
    (BACKLOG / "manifest.json").write_text(json.dumps(man, indent=2) + "\n")
    readme = """# Figure archive backlog

Queued batches of already-released articulated action figures (~180–250 each).
Every ~3 weeks, when New & Noteworthy promotes into the permanent archive,
the next unused `batch-NNN.json` is merged into `src/data/figures.ts`.

See also `docs/figure-backlog.md`.

## Batch file shape

`rows` match `figures.ts` Row tuples (optional 12th object: `{ sku?, exclusive? }`).
Statuses: `queued` → `injected` → never re-inject.
Action figures only — no pins, dolls, statues, plush, or apparel.
"""
    (BACKLOG / "README.md").write_text(readme)
    print("WROTE", out, "count", report["count"])


if __name__ == "__main__":
    main()
